import { registryProviderLogo } from "@lib/oauth-provider-registry";
import { bundledIntegrationLogo } from "@web/lib/integration-logos";
import { cn } from "@web/lib/utils";
import { Plug } from "lucide-react";
import { useState } from "react";

/**
 * Allow remote brand logos (integrations.sh catalog, etc.).
 * Reject javascript: and other non-http(s) schemes; data: is handled by registryProviderLogo.
 */
export function remoteIntegrationLogoUrl(logo: string | null | undefined): string | null {
  const trimmed = logo?.trim();
  if (!trimmed) return null;
  try {
    const parsed = new URL(trimmed);
    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return null;
    return parsed.toString();
  } catch {
    return null;
  }
}

export function IntegrationIcon({
  id,
  name,
  logo,
  className,
  fallbackClassName,
  decorative = false,
}: {
  id?: string;
  name: string;
  logo?: string | null;
  className?: string;
  fallbackClassName?: string;
  decorative?: boolean;
}) {
  const [remoteFailed, setRemoteFailed] = useState(false);
  const [registryFailed, setRegistryFailed] = useState(false);
  const [fallback, setFallback] = useState(false);

  const registrySrc = registryProviderLogo(logo);
  const remoteSrc = remoteIntegrationLogoUrl(logo);
  const bundledSrc = bundledIntegrationLogo(id);

  // Prefer explicit logo (data: or remote https), then bundled provider asset.
  let src: string | null = null;
  let kind: "registry" | "remote" | "bundled" | null = null;
  if (registrySrc && !registryFailed) {
    src = registrySrc;
    kind = "registry";
  } else if (remoteSrc && !remoteFailed) {
    src = remoteSrc;
    kind = "remote";
  } else if (bundledSrc) {
    src = bundledSrc;
    kind = "bundled";
  }

  if (fallback || !src) {
    return (
      <Plug
        aria-hidden={decorative}
        className={cn("size-6 shrink-0 text-muted-foreground/70", className, fallbackClassName)}
      />
    );
  }

  // Match catalog (integrations.sh) color logos to our monochrome marks.
  const toneClass =
    kind === "remote" ? "opacity-70 grayscale dark:invert" : "opacity-70 dark:invert";

  return (
    <img
      src={src}
      alt={decorative ? "" : name}
      className={cn("size-6 object-contain", toneClass, className)}
      referrerPolicy="no-referrer"
      loading="lazy"
      onError={() => {
        if (kind === "registry" && (remoteSrc || bundledSrc)) {
          setRegistryFailed(true);
          return;
        }
        if (kind === "remote" && bundledSrc) {
          setRemoteFailed(true);
          return;
        }
        setFallback(true);
      }}
    />
  );
}

